def mul(P,Q):
 out={}
 for d,c in P.items():
  for e,v in Q.items():add_term(out,tuple(x+y for x,y in zip(d,e)),c*v)
 return out

def power(P,n,N):
 R={(0,)*N:F(1)}
 for _ in range(n):R=mul(R,P)
 return R

def signed_mean(P,p,a):
 return sum((c*prod_mom(d,p,a) for d,c in P.items()),F(0))

def prod_mom(d,p,a):
 c=F(1)
 for i,n in enumerate(d):c*=moment(p,a[i],n)
 return c

sharp_cases=telescope_cases=linear_cases=0
for p in [2,4,6,8]:
 for N in [1,2,4]:
  for T in [F(1,2),F(3,2)]:
   a=[(-1)**(p//2+1)*T/N]*N
   X={}
   for j in range(N):
    d=[0]*N;d[j]=1;add_term(X,tuple(d),F(1))
   P=power(X,p-1,N)
   channels=[]
   for q in range(1,p):
